SELECT id, event_id AS eventId, channel_type AS channelType, target, content, status,
       deliver_state AS deliverState, attempt_count AS attemptCount, send_time AS sendTime
FROM warn_notify_log
WHERE event_id = #{eventId}
 AND channel_type = #{channelType} 
 AND send_time >= #{from} 
 AND send_time < #{to} 
ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM warn_notify_log
WHERE event_id = #{eventId}
 AND channel_type = #{channelType} 
 AND send_time >= #{from} 
 AND send_time < #{to}
